import sys; sys.path.insert(0, __import__("os").path.join(__import__("os").path.dirname(__file__), "..", "..", "pipeline"))
from scriptkit import sc, ch, save, S

# Grandma Ruth 89 · Everyday recipe: ham and bean soup

sc("""Sweetheart, after Christmas, every refrigerator in America has a ham bone sitting in it, wrapped in foil, waiting to be thrown away. Don't you dare throw it away. That bone is worth more than the whole ham. It makes the best soup you'll ever eat, thick and smoky, for about three dollars, enough to feed eight people. But most people's bean soup comes out thin, bland, and with beans that are hard as gravel.""",
   "ham bone wrapped in foil refrigerator", "DON'T THROW IT AWAY")
sc("""So tonight I'm giving you my mother's ham and bean soup, step by step, the way she made it every December twenty-sixth. And the five mistakes that ruin it. Stay with me, because the last secret is the reason her soup was so thick and creamy without a drop of cream, and it takes about ten seconds.""",
   "thick ham and bean soup in bowl", "THICK WITHOUT CREAM")

ch("The day after Christmas")
sc("""In our house, the day after Christmas was soup day. My mother would take the bone from the Christmas ham, put it in her biggest pot before anybody was awake, and by lunch, the whole house smelled smoky and warm. We'd eat it with cornbread, sitting around the kitchen table in our new Christmas sweaters, and nobody had to cook anything else all day.""",
   "family eating soup kitchen day after Christmas", "SOUP DAY")
sc("""Ham and beans was poor folks' food for three hundred years, honey. In the old days, a family would eat the ham at Christmas or Easter, and then that bone would feed them for another week. Beans were cheap. Onions were cheap. And a ham bone was free. In a minute I'll tell you how to get a ham bone even if you didn't make a ham.""",
   "old farmhouse kitchen pot on stove", "POOR FOLKS' FOOD")
sc("""In the Senate dining room in Washington, they've served bean soup made with a ham bone every single day since the early nineteen hundreds. It's a rule. Senators, presidents, every one of them. My father loved that. He'd say, Dorothy, we're eating like a senator today. And my mother would say, Walter, a senator never ate soup this good.""",
   "historic dining room Capitol building", "EATING LIKE A SENATOR")

ch("What you need")
sc("""Here's what you need. One meaty ham bone, or two smoked ham hocks. One pound of dried navy beans or great northern beans. One big onion, two carrots, and two stalks of celery, all chopped. Three cloves of garlic. Two bay leaves. A teaspoon of dried thyme. Ten cups of water or chicken broth. And black pepper. Don't add salt yet. I'll tell you why.""",
   "dried navy beans ham hock onions carrots", "THE INGREDIENTS")
sc("""And if you don't have a ham bone, honey, buy two smoked ham hocks at the meat counter for about four dollars. Or ask the butcher. Most grocery stores that sell spiral hams will give you the bone for almost nothing after Christmas. The ham hock has all the smoke and all the flavor, and the skin and gristle melt into the soup and make it rich.""",
   "smoked ham hocks at butcher counter", "ASK THE BUTCHER")

ch("The beans")
sc("""Mistake number one. Not soaking the beans. Put the dry beans in a big bowl, pick out any little stones or shriveled ones, and cover them with cold water by three inches. Leave them overnight. They'll double in size. In the morning, drain them and rinse them. Soaked beans cook evenly and they're much easier on your stomach, if you know what I mean.""",
   "beans soaking in bowl of water", "SOAK THEM OVERNIGHT")
sc("""Forgot to soak them? Here's my mother's quick soak. Put the beans in a pot, cover them with water, bring it to a boil for two minutes, then turn off the heat and let them sit with the lid on for one hour. Drain and rinse. It works almost as well. And mistake number two is using old beans. If that bag has been in your pantry for three years, they may never get soft.""",
   "boiling beans quick soak pot", "THE QUICK SOAK")

ch("The soup")
sc("""If this is helping you, tap the like button for me, sweetheart. It helps Grandma more than you know. Put the ham bone in your biggest pot with the drained beans, the bay leaves, the thyme, and the ten cups of water or broth. Bring it to a boil, then turn it down to a gentle simmer, with the lid tilted. Let it go for about an hour and a half.""",
   "ham bone and beans in big soup pot", "A GENTLE SIMMER")
sc("""Now, mistake number three. Adding salt at the beginning. The ham is already salty, and as the soup cooks down, it gets saltier. If you salt it now, it'll be like drinking seawater by dinnertime. And old cooks say salt early makes the bean skins tough. Wait until the very end, taste it, and then decide. Most of the time, it doesn't need any at all.""",
   "salt shaker next to soup pot", "NO SALT YET")
sc("""Mistake number four. Adding tomatoes or vinegar too early. Acid keeps beans from softening. If you like tomatoes in your bean soup, and some people do, add them only after the beans are completely tender. My Aunt Louise put a can of tomatoes in at the beginning one year, and those beans were still crunchy at midnight. My mother never let her forget it.""",
   "can of tomatoes beside pot", "ACID LATER")
sc("""After an hour and a half, add the chopped onion, carrots, celery, and garlic. Simmer another forty-five minutes, until the beans are creamy all the way through. Test one by squeezing it between your fingers. If it smashes easily with no hard center, they're done. If it fights you, keep going. Beans take as long as they take, honey.""",
   "adding vegetables to bean soup pot", "SQUEEZE A BEAN")

sc("""And if you're short on time, sweetheart, you can make it in a slow cooker. Put the soaked beans, the ham bone, the herbs, the vegetables and the water all in at once, and cook it on low for eight to nine hours while you're at work. It comes out just as good. Just don't use the quick soak for the slow cooker, and don't skip the soaking. Dry beans in a slow cooker sometimes never get soft.""",
   "slow cooker bean soup on counter", "THE SLOW COOKER WAY")
ch("The ham")
sc("""Now take out the ham bone and put it on a cutting board. Let it cool for a few minutes, then pull off every bit of meat with a fork and chop it up. Throw away the bone, the skin, and the gristle, and put the meat back in the pot. And fish out those bay leaves. My father bit into one once and said he'd been poisoned.""",
   "pulling ham meat off bone with fork", "PULL OFF EVERY BIT")

ch("The secret")
sc("""Now the secret I promised you, the ten-second trick. Mistake number five is thin, watery soup. Take two cups of the beans out with a ladle, put them in a bowl, and mash them with a potato masher or a fork until they're like paste. Stir them back into the pot. In two minutes, the whole soup turns thick and creamy and rich, like there's a pint of cream in it. And there's not a drop.""",
   "mashing beans with potato masher", "MASH TWO CUPS")
sc("""And then taste it, sweetheart. Now add salt if it needs it, and plenty of black pepper. And here's a little extra that my mother learned from a neighbor from Kentucky. A splash of cider vinegar right at the end, about a teaspoon. It makes the whole soup taste brighter and smokier at the same time. Taste before and after. You won't believe it.""",
   "splash of vinegar stirring soup", "A SPLASH AT THE END")
sc("""And give it time. Like every bean soup, it's better the next day, after the flavors have had a night together in the icebox. It thickens a lot overnight, so add a little water or broth when you warm it up. It keeps five days in the icebox and three months in the freezer. I freeze it in quart jars, and it's a winter's worth of lunches.""",
   "soup in quart jars freezer", "BETTER THE NEXT DAY")

sc("""Here's a trick for a smokier soup, honey, when your ham bone doesn't have much meat left on it. Brown a few slices of chopped bacon in the pot first, take them out, and cook your onions in the bacon grease before you add everything else. Then stir the crispy bacon in at the end. My son-in-law does it that way, and I'll admit he's right.""",
   "chopped bacon browning in soup pot", "A LITTLE BACON")
ch("Serving it")
sc("""Serve it in big bowls with a square of cornbread, sweetheart. In Ohio and Kentucky, a lot of people crumble the cornbread right into the soup. Some put a little chopped raw onion on top, which my father loved. And a bottle of hot sauce on the table for anybody who wants it. Nothing else. That's a whole meal, and it'll keep you warm all afternoon.""",
   "bean soup with cornbread and onion", "WITH CORNBREAD")
sc("""When my children were little, the day after Christmas, I'd make a pot of ham and bean soup and a pan of cornbread, and we'd take a big bowl next door to Mrs. Kowalski, who lived alone. And then we'd all go sledding. It's still my favorite day of the whole Christmas season, honey. Quieter than Christmas. No presents. Just soup, and snow, and people you love.""",
   "family sledding after Christmas snow", "MY FAVORITE DAY")

ch("Grandma's kitchen")
sc("""So one more time. Save the ham bone, or buy a smoked hock. Soak your beans, and use fresh ones. Simmer them gently with the bone. No salt and no tomatoes until the end. Add the vegetables later. Pull off the ham. Mash two cups of beans and stir them back in. And a splash of vinegar. That's my mother's soup, and it's the best thing you'll eat all winter.""",
   "pot of ham and bean soup on table", "THE BEST OF WINTER")
sc("""Tell me in the comments, sweetheart. Cornbread in your soup, or on the side? I want to know which team you're on. The whole playlist of Grandma's recipes is right there on your screen, and I'll see you in the next video. Good night, honey.""",
   "kitchen window snowy day steam", "IN OR ON THE SIDE?")

for s in S:
    s["cuts"], s["moves"] = 4, True

save("grandma89", "Ham and Bean Soup EVERYONE's Grandma Made (Why Yours Is WATERY)",
     ["Grandma Ruth is a narrated character built from real memories and records of the era.",
      "Bean soup made with ham has been served in the U.S. Senate dining room daily since the early 20th century.",
      "Recipe as written by Grandma Ruth: 1 meaty ham bone or 2 smoked ham hocks, 1 lb dried navy or great northern beans (soaked), onion, 2 carrots, 2 celery stalks, 3 garlic cloves, 2 bay leaves, 1 tsp thyme, 10 cups water or broth; 2 cups beans mashed and returned; salt and 1 tsp cider vinegar at the end."],
     "everyday recipe", minutes=(10, 14.5), voice="en_US-lessac-high")
